PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,claude_session_id TEXT,title TEXT NOT NULL,title_user_edited INTEGER NOT NULL DEFAULT 0,summary TEXT NOT NULL DEFAULT '',project_id TEXT,parent_conversation_id TEXT,favorite INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,no_memory INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,role TEXT NOT NULL,content_text TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE memories(id TEXT PRIMARY KEY,type TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,normalized_key TEXT NOT NULL,project_id TEXT,source_conversation_id TEXT,confidence REAL NOT NULL,importance REAL NOT NULL,explicit INTEGER NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,disabled INTEGER NOT NULL DEFAULT 0,superseded_by TEXT,last_used_at TEXT,use_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,root_path TEXT NOT NULL,tags_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY,title TEXT NOT NULL,status TEXT NOT NULL,due_at TEXT,recurrence_json TEXT,project_id TEXT,conversation_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,json_value TEXT NOT NULL);
CREATE TABLE module_configs(module_id TEXT PRIMARY KEY,enabled INTEGER NOT NULL,config_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE connections(id TEXT PRIMARY KEY,module_id TEXT NOT NULL,name TEXT NOT NULL,config_json TEXT NOT NULL,secret_ref TEXT,health TEXT NOT NULL DEFAULT 'LIVE_NOT_RUN');
CREATE TABLE permission_requests(id TEXT PRIMARY KEY,tool_id TEXT NOT NULL,risk TEXT NOT NULL,input_json_redacted TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE permission_rules(id TEXT PRIMARY KEY,tool_id TEXT NOT NULL,scope_json TEXT NOT NULL,session_id TEXT,expires_at TEXT,decision TEXT NOT NULL);
CREATE TABLE activity_events(id TEXT PRIMARY KEY,timestamp TEXT NOT NULL,tool_id TEXT NOT NULL,kind TEXT NOT NULL,risk TEXT NOT NULL,input_summary TEXT NOT NULL,output_summary TEXT NOT NULL,status TEXT NOT NULL,duration_ms INTEGER NOT NULL DEFAULT 0,undo_token TEXT);
CREATE TABLE tool_runs(id TEXT PRIMARY KEY,tool_id TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,error_code TEXT);
CREATE TABLE attachments(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),path TEXT NOT NULL,mime TEXT NOT NULL,sha256 TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE macros(id TEXT PRIMARY KEY,name TEXT NOT NULL,definition_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE custom_tools(id TEXT PRIMARY KEY,manifest_json TEXT NOT NULL,install_path TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE monitors_state(monitor_fingerprint TEXT PRIMARY KEY,scale REAL NOT NULL,work_area TEXT NOT NULL,pet_x_normalized REAL NOT NULL,last_seen TEXT NOT NULL);
CREATE TABLE memory_sources(memory_id TEXT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,conversation_id TEXT,message_id TEXT);
CREATE TABLE task_runs(id TEXT PRIMARY KEY,task_id TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,result_summary TEXT);
CREATE TABLE semantic_documents(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,model_id TEXT NOT NULL,vector_blob BLOB NOT NULL,text_hash TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE VIRTUAL TABLE conversations_fts USING fts5(id UNINDEXED,title,summary);
CREATE VIRTUAL TABLE messages_fts USING fts5(id UNINDEXED,conversation_id UNINDEXED,content_text);
CREATE VIRTUAL TABLE memories_fts USING fts5(id UNINDEXED,title,content);
CREATE VIRTUAL TABLE projects_fts USING fts5(id UNINDEXED,name,tags_json);
CREATE TRIGGER conversations_ai AFTER INSERT ON conversations BEGIN INSERT INTO conversations_fts VALUES(new.id,new.title,new.summary); END;
CREATE TRIGGER conversations_au AFTER UPDATE ON conversations BEGIN DELETE FROM conversations_fts WHERE id=old.id; INSERT INTO conversations_fts VALUES(new.id,new.title,new.summary); END;
CREATE TRIGGER conversations_ad AFTER DELETE ON conversations BEGIN DELETE FROM conversations_fts WHERE id=old.id; END;
CREATE TRIGGER messages_ai AFTER INSERT ON messages BEGIN INSERT INTO messages_fts VALUES(new.id,new.conversation_id,new.content_text); END;
CREATE TRIGGER messages_au AFTER UPDATE ON messages BEGIN DELETE FROM messages_fts WHERE id=old.id; INSERT INTO messages_fts VALUES(new.id,new.conversation_id,new.content_text); END;
CREATE TRIGGER messages_ad AFTER DELETE ON messages BEGIN DELETE FROM messages_fts WHERE id=old.id; END;
CREATE TRIGGER memories_ai AFTER INSERT ON memories BEGIN INSERT INTO memories_fts VALUES(new.id,new.title,new.content); END;
CREATE TRIGGER memories_au AFTER UPDATE ON memories BEGIN DELETE FROM memories_fts WHERE id=old.id; INSERT INTO memories_fts VALUES(new.id,new.title,new.content); END;
CREATE TRIGGER memories_ad AFTER DELETE ON memories BEGIN DELETE FROM memories_fts WHERE id=old.id; END;
CREATE TRIGGER projects_ai AFTER INSERT ON projects BEGIN INSERT INTO projects_fts VALUES(new.id,new.name,new.tags_json); END;
CREATE TRIGGER projects_ad AFTER DELETE ON projects BEGIN DELETE FROM projects_fts WHERE id=old.id; END;
PRAGMA user_version=1;
